#include <istream>
#include <string>

int sum_numbers(std::istream& in) {
    int total = 0;
    for (int n; ; ) {
        if (in >> n) {
            total += n;
        } else if (in.eof()) {
            break;
        } else {
            in.clear();          // the bad characters are still in the buffer
        }
    }
    return total;
}

