solution:
#include <istream>
#include <string>

int sum_numbers(std::istream& in) {
    int total = 0;
    for (int n; ; ) {
        if (in >> n) {
            total += n;
        } else if (in.eof()) {
            break;
        } else {
            in.clear();
            std::string junk;
            in >> junk;          // consume the token that would not parse
        }
    }
    return total;
}
